import StatisticsCards from "@/components/cards/StatisticsCards";
import GroupIcon from "@/components/icons/user/GroupIcon";
import MinusUserIcon from "@/components/icons/user/MinusUserIcon";
import TwoUsersIcon from "@/components/icons/user/TwoUsersIcon";
import UserRemoveIcon from "@/components/icons/UserRemoveIcon";
import { employeesStats } from "@/features/humanResources/types/employeesStats.types";
import { endpoints } from "@/lib/axios/axios-global";
import { apiGet } from "@/lib/axios/axios-utils";
import { Card } from "@/types/statistics";
import { useEffect, useState } from "react";
import DeductionsList from "../components/payrollList/DeductionsList";

const Deductions = () => {
    const [stats, setStats] = useState<employeesStats | null>(null);

    useEffect(() => {
        const fetchStats = async () => {
            try {
                const res = await apiGet({ endpoint: endpoints.payroll.dashboard });
                setStats(res.data.data);
            } catch (err) {
                setStats(null);
            }
        };
        fetchStats();
    }, []);

    const cards: Card[] = [
        { text: 'إجمالي الخصومات', num: stats?.total_employees, percent: 12, icon: <GroupIcon /> },
        { text: 'عدد الموظفين', num: stats?.total_employees, percent: 0, icon: <UserRemoveIcon />, label: 'موظف' },
        { text: 'متوسط الخصومات', num: stats?.total_full_time, percent: -0.3, icon: <TwoUsersIcon /> },
        { text: 'الخصومات', num: stats?.total_part_time, percent: -0.3, icon: <MinusUserIcon /> },
    ];

    return (
        <div className="w-full mt-6 mb-20">

            <StatisticsCards cards={cards} className="mt-6" />
            <DeductionsList />
        </div>
    );
};

export default Deductions;
